const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nice=x=>esc(String(x??'').replaceAll('_',' '));
const pill=x=>`<span class="pill ${esc(x)}">${nice(x)}</span>`;
const fmt=x=>esc(String(x??'').replace(' ',' · '));
const route=location.pathname;const patientStorageKey='octopus_selected_patient';let personId=new URLSearchParams(location.search).get('id')||localStorage.getItem(patientStorageKey)||'',state,openings=[];let personasById={};
const titles={'/patient/':['Welcome to AIDE','Your personal appointment hub.'],'/patient/find':['Find care','Browse released appointments and explore your options.'],'/patient/appointments':['My appointments','Track your held and confirmed appointments.'],'/patient/offers':['My offers','Respond to time-sensitive appointment opportunities.'],'/patient/preferences':['My preferences','See the preferences used for matching.']};const title=titles[route]||titles['/patient/'];$('pageTitle').textContent=title[0];$('pageSub').textContent=title[1];document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));
async function req(url,options){const r=await fetch(url,options),j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j;}
const link=path=>path+'?id='+encodeURIComponent(personId);
const cardAppt=s=>`<div class="patient-feature"><div class="flex"><strong>${nice(s.service_type)} · ${nice(s.visit_type)}</strong>${pill(s.status)}</div><p>${fmt(s.start_at)}–${esc(s.end_at.slice(-5))} · ${esc(s.duration_min)} min</p><div class="muted">${esc(state.clinic_names[s.clinic_id]||s.clinic_id)} · ${esc(s.provider_id)}</div></div>`;
const cardOffer=o=>`<div class="patient-feature"><div class="flex"><strong>${nice(o.slot.service_type)} · ${nice(o.slot.visit_type)}</strong>${pill(o.state)}</div><p>${fmt(o.slot.start_at)} · ${esc(o.slot.duration_min)} min</p><p class="muted">${esc(state.clinic_names[o.slot.clinic_id]||o.slot.clinic_id)} · ${esc(o.slot.provider_id)}</p>${o.state==='offered'?`<p>This appointment matches your saved request. Accept or decline the simulated offer. Expires at ${esc(o.expires_at||"demo deadline")}; simulated time ${esc(o.simulation_now||"not set")}.</p><div class="row"><button data-accept="${esc(o.id)}">Accept offer</button><button class="secondary" data-decline="${esc(o.id)}">No thanks</button></div>`:o.state==='held'?'<div class="hint">Your slot is being held. Please wait for clinic confirmation.</div>':o.state==='confirmed'?'<div class="hint">Your appointment is confirmed.</div>':`<p class="muted">Offer ${esc(o.state)}. Your existing request remains unchanged.</p>`}</div>`;
function home(){const offered=state.offers.filter(o=>o.state==='offered'),booked=state.appointments.filter(a=>a.status==='confirmed');return `<div class="patient-layout"><div><div class="patient-hero"><div class="eyebrow">YOUR CARE, YOUR TIMING</div><h2 style="font-size:28px;margin:9px 0">Hello, ${esc(state.patient.display_name||personId)} 👋</h2><p>Discover a more convenient appointment or respond to an earlier-time offer.</p><div class="quick-actions"><a class="link-btn" href="${link('/patient/find')}">Find care →</a><a class="link-btn" href="${link('/patient/offers')}">View my offers ${offered.length?'('+offered.length+')':''} →</a></div></div><section class="card" style="margin-top:18px"><h2>What's next?</h2>${offered.length?cardOffer(offered[0]):`<div class="blank">No new offers for this patient. A receptionist can release an appointment in the Clinic portal and send eligible patients offers.</div>`}</section></div><div><section class="card"><h2>My latest booking</h2>${booked.length?cardAppt(booked[0]):'<div class="blank">No confirmed replacement appointment yet.</div>'}<p><a class="textlink" href="${link('/patient/appointments')}">View appointments →</a></p></section><section class="card" style="margin-top:18px"><h2>My request</h2><p><strong>${nice(state.patient.service_type)} · ${nice(state.patient.visit_type)}</strong></p><p class="muted">Availability: ${fmt(state.patient.available_start)} through ${fmt(state.patient.available_end)}</p><a class="textlink" href="${link('/patient/preferences')}">View saved preferences →</a></section></div></div>`;}
function findCare(){return `<div class="patient-layout"><section class="card"><h2>Available time search</h2><p class="muted">Browse openings published by the demo clinic. Individual eligibility is checked by the matching engine before automatic offers; these results aren't guaranteed bookable.</p><div class="formfield"><label>Requested treatment</label><input value="${esc(state.patient.service_type)}" disabled aria-label="Requested treatment"></div><div class="formfield"><label>Visit type</label><input value="${esc(state.patient.visit_type)}" disabled aria-label="Visit type"></div><p class="hint">Search is read-only in v0.4. To demonstrate booking, use the clinic's recovery screen to send an offer and then accept it in My Offers.</p></section><section class="card"><div class="flex"><h2>Currently released openings</h2><span class="muted">${openings.length} openings</span></div>${openings.length?openings.map(s=>`<div class="browse-result"><strong>${nice(s.service_type)}</strong><p>${fmt(s.start_at)} · ${esc(s.duration_min)} min</p><div class="muted">${esc(state.clinic_names[s.clinic_id]||s.clinic_id)} · ${esc(s.provider_id)}</div>${pill(s.status)}<p class="muted">Contact clinic or wait for an eligible offer in this demo.</p></div>`).join(''):'<div class="blank">No released appointment openings yet.</div>'}</section></div>`;}
function appointments(){return `<div class="patient-focus"><section class="card"><h2>My bookings</h2>${state.appointments.length?state.appointments.map(cardAppt).join(''):'<div class="blank">No held or confirmed replacement bookings in this fictional account.</div>'}<div class="divider"></div><p class="muted">Original demo bookings belong to separate fictional patients and are not displayed here. This portal shows only this persona’s replacement bookings.</p><a class="link-btn" href="${link('/patient/offers')}">Check offers →</a></section></div>`;}
function offers(){const active=state.offers.filter(o=>o.state==='offered'),other=state.offers.filter(o=>o.state!=='offered');return `<div class="patient-focus"><section class="card"><div class="flex"><h2>Appointment offers</h2><span class="pill offered">${active.length} waiting</span></div><p class="muted">Offers are simulated within this local prototype; no SMS or email is sent.</p>${active.length?active.map(cardOffer).join(''):'<div class="blank">No offers awaiting your response.</div>'}</section>${other.length?`<section class="card" style="margin-top:16px"><h2>Offer history</h2>${other.slice().reverse().map(cardOffer).join('')}</section>`:''}</div>`;}
function prefs(){const p=state.patient;return `<div class="patient-layout"><section class="card"><h2>Appointment preferences</h2><div class="prefs-display"><div><strong>Service</strong>${nice(p.service_type)}</div><div><strong>Visit type</strong>${nice(p.visit_type)}</div><div><strong>Duration</strong>${esc(p.required_duration_min)} min</div><div><strong>Preferred clinic</strong>${nice(p.clinic_preference)}</div><div><strong>Practitioner</strong>${esc(p.preferred_provider_id||'Any')}</div><div><strong>Must use preferred practitioner?</strong>${p.provider_required==='True'?'Yes':'No'}</div></div></section><section class="card"><h2>Availability & offer settings</h2><div class="prefs-display"><div><strong>Available from</strong>${fmt(p.available_start)}</div><div><strong>Available until</strong>${fmt(p.available_end)}</div><div><strong>Estimated travel</strong>${esc(p.travel_min)} min</div><div><strong>Active request</strong>${p.active_request==='True'?'Yes':'No'}</div><div><strong>Offers enabled</strong>${p.opt_in==='True'?'Yes':'No'}</div></div><p class="hint" style="margin-top:16px">Preferences are currently read-only. They are loaded from synthetic CSVs and used during matching; editing and saving them is planned for a subsequent iteration.</p></section></div>`;}
function render(){let html=route.includes('/find')?findCare():route.includes('/appointments')?appointments():route.includes('/offers')?offers():route.includes('/preferences')?prefs():home();$('patientContent').innerHTML=html;document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>respond(b.dataset.accept,'accept'));document.querySelectorAll('[data-decline]').forEach(b=>b.onclick=()=>respond(b.dataset.decline,'decline'));}
async function respond(offer_id,choice){try{await req('/api/patient/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'respond',offer_id,choice,patient_id:personId})});$('error').textContent='';await refresh();}catch(e){$('error').textContent=e.message;}}
async function refresh(){try{state=await req('/api/patient/state?id='+encodeURIComponent(personId));if(route.includes('/find'))openings=(await req('/api/patient/openings')).openings;$('error').textContent='';render();}catch(e){$('error').textContent=e.message;}}
function syncPatientSelection(){
  localStorage.setItem(patientStorageKey,personId);
  const url=new URL(location.href);url.searchParams.set('id',personId);
  history.replaceState(null,'',url.pathname+url.search);
  $('persona').value=personId;
  document.querySelectorAll('[data-route]').forEach(a=>a.href=link(a.dataset.route));
}
function patientOptions(filter=''){
  const search=filter.trim().toLocaleLowerCase();
  const matching=Object.entries(personasById)
    .filter(([id,name])=>`${name} ${id}`.toLocaleLowerCase().includes(search))
    .sort((a,b)=>a[1].localeCompare(b[1])||a[0].localeCompare(b[0]));
  // Keep the currently active account visible even while searching for another name.
  if(!matching.some(([id])=>id===personId) && personasById[personId]) matching.unshift([personId,personasById[personId]]);
  $('persona').innerHTML=matching.map(([id,name])=>`<option value="${esc(id)}">${esc(name)} · ${esc(id)}</option>`).join('');
  $('persona').value=personId;
  $('patientSearchInfo').textContent=search?`${matching.length-(matching.some(([id])=>id===personId)&&!(`${personasById[personId]} ${personId}`.toLocaleLowerCase().includes(search))?1:0)} matching patients`:`${matching.length} fictional patients`;
}
async function boot(){try{
  const personas=await req('/api/demo/personas');
  personasById=personas.patient_names;
  const p=personas.patient_ids;
  if(!p.includes(personId))personId=p[0];
  syncPatientSelection();patientOptions();
  $('patientSearch').addEventListener('input',e=>patientOptions(e.target.value));
  $('patientSearch').addEventListener('keydown',e=>{
    if(e.key==='Enter'){
      const q=e.target.value.trim().toLocaleLowerCase();
      const first=Object.entries(personasById).sort((a,b)=>a[1].localeCompare(b[1])).find(([id,name])=>`${name} ${id}`.toLocaleLowerCase().includes(q));
      if(first){personId=first[0];syncPatientSelection();patientOptions(e.target.value);refresh();}
    }
  });
  $('persona').onchange=()=>{personId=$('persona').value;syncPatientSelection();patientOptions($('patientSearch').value);refresh();};
  await refresh();
}catch(e){$('error').textContent=e.message;}}
boot();setInterval(()=>{if(!document.hidden&&personId)refresh();},6000);
